WITH matched_keys AS (SELECT customer_id, plan FROM subscriptions INTERSECT ALL SELECT customer_id, plan FROM subscriptions WHERE MONTH(end_date) IN (1, 5, 7)), verified AS (SELECT s.* FROM subscriptions s JOIN matched_keys k ON s.customer_id = k.customer_id AND s.plan = k.plan) SELECT id, customer_id, plan, start_date, end_date, monthly_fee, status FROM verified ORDER BY end_date DESC
